using System.ComponentModel.DataAnnotations;
namespace CoracaoAnimal.Core;
public sealed record Cadastro([property:Required,StringLength(150,MinimumLength=2)]string Nome,[property:Required,EmailAddress,StringLength(254)]string Email,[property:Required,StringLength(128,MinimumLength=10)]string Senha);
public sealed record Login([property:Required,EmailAddress,StringLength(254)]string Email,[property:Required,StringLength(128)]string Senha,string Cliente="web");
public sealed record PerfilInput([property:Required,StringLength(150,MinimumLength=2)]string Nome,[property:StringLength(14)]string? Cpf,[property:StringLength(20)]string Telefone,[property:StringLength(255)]string Endereco,string EspeciePreferida="cao",string Espaco="medio",string Experiencia="alguma");
public sealed record SenhaInput([property:Required,StringLength(128)]string Atual,[property:Required,StringLength(128,MinimumLength=10)]string Nova);
public sealed record UsuarioDto(int Id,string Nome,string Email,string Papel,string? Cpf,string Telefone,string Endereco,string EspeciePreferida,string Espaco,string Experiencia);
public sealed record SessaoDto(UsuarioDto Usuario,string? Token,DateTime ExpiraEm);
public sealed record AnimalInput([property:Required,StringLength(100)]string Nome,string Especie,[property:StringLength(80)]string Raca,[property:Range(0,40)]int Idade,string Porte,string Status,[property:StringLength(4000)]string Descricao);
public sealed record AnimalDto(int Id,string Nome,string Especie,string Raca,int Idade,string Porte,string Status,string Descricao,string? FotoUrl,double? Compatibilidade=null);
public sealed record AdocaoInput([property:Range(1,int.MaxValue)]int AnimalId,[property:StringLength(2000)]string Observacoes,bool AceitaTermos);
public sealed record AdocaoDto(int Id,int AnimalId,string AnimalNome,string? FotoUrl,string Status,string Observacoes,DateTime CriadoEm,DateTime AtualizadoEm,string? AdotanteNome=null);
public sealed record DoacaoInput([property:Range(typeof(decimal),"1","1000000")]decimal Valor,string FormaPagamento,[property:StringLength(255)]string Descricao,bool Anonima);
public sealed record DoacaoDto(int Id,decimal Valor,string FormaPagamento,string Status,string Descricao,bool Anonima,DateTime CriadoEm,string? DoadorNome=null);
public sealed record VoluntarioInput([property:Required,StringLength(100,MinimumLength=2)]string Area,[property:Required,StringLength(500,MinimumLength=2)]string Disponibilidade);
public sealed record VoluntarioDto(int Id,string Area,string Disponibilidade,string Status,DateTime CriadoEm,string? Nome=null,string? Email=null);
public sealed record StatusInput(string Status);
public sealed record Pagina<T>(IReadOnlyList<T> Itens,int Total,int PaginaAtual,int Tamanho);
public sealed record ResumoDto(int AnimaisDisponiveis,int AdocoesPendentes,int AdocoesConcluidas,decimal DoacoesConfirmadas,int VoluntariosAtivos);
